<?php
namespace App\Models;
use Illuminate\Database\Eloquent\{Model,SoftDeletes};
class SubscriptionPlan extends Model{use SoftDeletes;protected $guarded=['id'];protected $casts=['is_active'=>'boolean','is_public'=>'boolean','is_recommended'=>'boolean','photo_storage_limit'=>'integer','photo_reuse_limit'=>'integer','video_storage_mb'=>'integer','team_seat_limit'=>'integer','group_limit'=>'integer','guest_limit'=>'integer','version'=>'integer'];public function prices(){return$this->hasMany(SubscriptionPlanPrice::class);}public function features(){return$this->belongsToMany(SubscriptionFeature::class,'subscription_plan_features')->using(SubscriptionPlanFeature::class)->withPivot(['id','is_included','value_boolean','value_integer','value_decimal','value_text','is_addon','addon_price_paise','display_label','display_order'])->withTimestamps();}public function subscriptions(){return$this->hasMany(Subscription::class);}public function audits(){return$this->hasMany(SubscriptionPlanAudit::class);}public function currentPrice(string$i){return$this->prices()->where('billing_interval',$i)->where('is_active',true)->where('effective_from','<=',now())->where(fn($q)=>$q->whereNull('effective_until')->orWhere('effective_until','>',now()))->latest('effective_from')->first();}}
